+// Sites: each location belongs to one site, so a batch (which sits in a
+// location) belongs to the site of its location. Items, suppliers, recipes
+// and dishes are shared by all sites.
+import { AppError } from "../errors.js";
+
+/** The site used when a request names none. */
+export const DEFAULT_SITE = "main";
+
+/** The site `id`, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** True when the batch sits in a location of `site`. */
+export function inSite(store, batch, site) {
+  return store.data.locations.some((l) => l.id === batch.location && l.site === site);
+}
+
+/** True when `location` is a location of `site`. */
+export function hasLocation(store, location, site) {
+  return store.data.locations.some((l) => l.id === location && l.site === site);
+}
