diff --git a/tests/sites.test.js b/tests/sites.test.js
new file mode 100644
index 0000000..a106575
--- /dev/null
+++ b/tests/sites.test.js
@@ -0,0 +1,38 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "x-larder-site": "annex" };
+
+test("an unknown site is a 400 unknown_site", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "X-Larder-Site": "nope" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+});
+
+test("the annex sees no stock, main is the default", async () => {
+  const { handle } = app();
+  const main = await handle({ path: "/items/1" });
+  assert.equal(main.body.onHand, 10);
+  const other = await handle({ path: "/items/1", headers: annex });
+  assert.equal(other.body.onHand, 0);
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body, []);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 0);
+});
+
+test("receiving, cooking and stock-takes are per site", async () => {
+  const { handle } = app();
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 4 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const bad = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots: [{ lot: "A", location: "dry" }] }, headers: annex });
+  assert.equal(bad.body.error.code, "unknown_location");
+  const ok = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots: [{ lot: "A", location: "annex-fridge" }] }, headers: annex });
+  assert.equal(ok.status, 200);
+  assert.equal((await handle({ path: "/items/1", headers: annex })).body.onHand, 4);
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 10);
+  const st = await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } });
+  assert.equal(st.body.error.code, "unknown_location");
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" }, headers: annex })).status, 201);
+});
